int main() {
    int n;
    double total = 0.0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int producto;
        double precio;
        scanf("%d %lf", &producto, &precio);
        total += precio;
    }
    printf("%.2f\n", total / n);
    return 0;
}

