#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);
    int ventasA = 0, ventasB = 0, ventasC = 0;
    for (int i = 0; i < n; i++) {
        int producto;
        double precio;
        scanf("%d %lf", &producto, &precio);
        if (producto == 1) {
            ventasA++;
        } else if (producto == 2) {
            ventasB++;
        } else if (producto == 3) {
            ventasC++;
        }
    }
    printf("Ventas por categoria:\nA: %d\nB: %d\nC: %d\n", ventasA, ventasB, ventasC);
    return 0;
}
